import{z as i,x as p,o as r,c as A,q as o,j as t,D as e,d as n,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Sora","description":"","frontmatter":{"title":"Sora","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sora.md","filePath":"llm/sora.md","lastUpdated":1791413859000}'),B={name:"llm/sora.md"};function d(m,a,h,c,D,T){const E=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="sora" tabindex="-1">Sora <a class="header-anchor" href="#sora" aria-label="Permalink to &quot;Sora&quot;">​</a></h1><div class="epigraph"><p>我们在可变时长、分辨率与宽高比的视频和图像上联合训练文本条件扩散；骨干是作用在时空 patch 上的 Transformer。最大的模型 Sora 能生成一分钟高保真视频。</p><footer>—— OpenAI, Video generation models as world simulators, 2024-02-15</footer></div><p>OpenAI 在 2024 年 2 月 15 日公开技术博客 <em>Video generation models as world simulators</em>，把 Sora 写成一条缩放叙事：像语言模型用 token 统一模态那样，用时空 patch 统一可变视频与图像。先把像素压进时空都压缩的潜空间，再切成 patch 当 Transformer token，扩散模型从噪声 patch 预测干净 patch。产品页 <em>Creating video from text</em> 展示文生视频、图生视频、延长与编辑。博客写明：<strong>不含模型与实现细节</strong>。闭源视频模型只以官方博客为准，不引用第三方「逆向工程」论文里的层数、损失或数据表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>此前视频生成多把素材裁成固定方形、固定秒数，再在同一格子里训练。真实视频宽高比与时长是分布，不是超参。裁切丢掉构图；统一长度迫使模型在填充或截断里浪费容量。像素空间逐步去噪对高分辨率长视频不可行，需要压缩；压缩若只做空间、不做时间，时间维仍然爆炸。</p>',5)),(r(),t(l,null,{default:e(()=>[s(E,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E8%A7%86%E9%A2%91%EF%BC%9A%E5%90%84%E7%A7%8D%E5%AE%BD%E9%AB%98%E6%AF%94%E4%B8%8E%E6%97%B6%E9%95%BF%22%5D%20--%3E%20Q%7B%22%E9%A2%84%E5%A4%84%E7%90%86%E7%AD%96%E7%95%A5%22%7D%0A%20%20Q%20--%3E%7C%22%E8%A3%81%E6%88%90%E5%9B%BA%E5%AE%9A%E6%96%B9%E5%BD%A2%E3%80%81%E5%9B%BA%E5%AE%9A%E7%A7%92%E6%95%B0%22%7C%20CROP%5B%22%E8%A3%81%E5%88%87%E4%B8%A2%E6%9E%84%E5%9B%BE%EF%BC%8C%E5%A1%AB%E5%85%85%E6%88%AA%E6%96%AD%E6%B5%AA%E8%B4%B9%E5%AE%B9%E9%87%8F%22%5D%0A%20%20Q%20--%3E%7C%22%E6%97%B6%E7%A9%BA%20patch%20%E5%8E%9F%E7%94%9F%E8%A1%A8%E8%BE%BE%22%7C%20NATIVE%5B%22%E6%97%B6%E9%95%BF%E5%88%86%E8%BE%A8%E7%8E%87%20%3D%20%E4%B8%8D%E5%90%8C%E7%9A%84%20token%20%E7%BD%91%E6%A0%BC%22%5D%0A%20%20CROP%20--%3E%20LOSE%5B%22%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E4%B8%8D%E7%AD%89%E4%BA%8E%E7%9C%9F%E5%AE%9E%E5%88%86%E5%B8%83%22%5D%0A%20%20NATIVE%20--%3E%20KEEP%5B%22%E6%9E%84%E5%9B%BE%E4%BF%9D%E7%95%99%EF%BC%8C%E8%BE%93%E5%87%BA%E5%BD%A2%E7%8A%B6%E5%8F%AF%E8%B0%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>第二个问题是语言对齐。视频标题嘈杂，短提示不够描述镜头。若没有接近 DALL·E 3 的重描述，文本条件会弱于图像模型已经达到的遵从度。OpenAI 把问题收成：一种表示吃下所有视觉数据，一种可缩放的生成器，一种语言预处理。</p><h3 id="世界模拟器是观察-不是规格" tabindex="-1">世界模拟器是观察，不是规格 <a class="header-anchor" href="#世界模拟器是观察-不是规格" aria-label="Permalink to &quot;世界模拟器是观察，不是规格&quot;">​</a></h3><p>博客用 3D 一致性、物体持久、摄像机运动、与世界互动、甚至游戏世界来论证「缩放视频生成是通向通用物理模拟器的一条路」。同时列出失败：物理（玻璃该碎不碎）、因果（动作与反作用）、空间细节（左右）、文字渲染、长时一致性。把 Sora 写成已完成的物理引擎，过读；写成「像素时间序列上的扩散 Transformer」，才是博客给出的方法学。</p><p><span class="marginnote">技术报告明确两件事：统一表示与定性能力/局限。权重、深度、训练步数、数据配比、采样器均未公开。产品后来的 Turbo、Sora 2 是后续博客，不要倒填进 2024 年 2 月这篇。比较 <a href="/llm/veo-3">Veo 3</a> 时只比双方官方当时写过的能力，不比未公开的骨干图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>视频压缩网络：输入原始视频，输出在时间与空间上都降维的潜变量；Sora 在该潜空间训练与生成。对应的解码器把潜变量映回像素。图像视为单帧视频，走同一压缩。博客把这一步与「先压缩再生成」的潜空间传统对齐，但不给出通道数或压缩比。</p><p>时空 patch：在压缩后的体积上切块，每块跨一小片空间与一小段时间，作为 Transformer token。不同时长、分辨率、宽高比变成不同的 token 网格，而不是强制同一张量形状。推理时通过安排随机初始化 patch 的网格大小控制输出分辨率与时长。训练联合视频与图像。生成器是扩散 Transformer：给定噪声 patch 与文本等条件，预测干净 patch。博客引用扩散与 <a href="/llm/dit-architecture">DiT</a> 的缩放，并展示固定种子下训练计算增加则样本变好。</p><p><span class="marginnote">直觉类比：语言模型把句子切成 token，Sora 把视频切成带时间戳的「积木块」——每块既占一小片画面，也占一小段时间。换视频长度或分辨率，只是积木数量与排布变了，积木还是同一种，一套权重就能处理所有尺寸。</span></p><h3 id="语言、条件与编辑接口" tabindex="-1">语言、条件与编辑接口 <a class="header-anchor" href="#语言、条件与编辑接口" aria-label="Permalink to &quot;语言、条件与编辑接口&quot;">​</a></h3><p>文本条件方面，博客写到用视频—文本模型做描述，并采用类似 DALL·E 3 的重描述，把短提示扩成详细镜头语言。接口包括文生视频、把静态图当首帧做图生视频、向前或向后延长、在视频上做编辑。这些是产品能力列表，不是可复现的条件注入公式（交叉注意力或 adaLN 均未写）。原生宽高比训练被写成保留构图，避免方形裁切带来的主体残缺。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Token 统一是核心机制：一旦视觉是 patch 序列，时长与分辨率就是序列长度与网格形状，计算随 token 数涨，与 DiT 用 Gflops 而不是参数解释质量的逻辑一致。时间维压缩让一分钟视频的 token 预算可训练，否则帧数直接乘空间 patch 会爆。扩散提供迭代修订：整段时空草稿同时存在，理论上可修全局一致性，这与自回归逐帧不同——博客没有给出自回归视频对照实验，只给扩散 Transformer 的定性缩放。</p><p><span class="marginnote">数字实例：一帧 1080p 图像约 200 万像素，60 秒、30 fps 的视频就是约 1800 帧、37 亿个像素级单元；不压缩直接当 token，任何 Transformer 都吃不下。「先压潜空间、再切 patch」就是把天文数字折算进序列长度预算的那一步。</span></p><p>涌现能力按博客自己的例子理解：镜头绕物体转时身份大致保持，是 3D 一致性的观感；物体暂时出画再回来仍在，是持久性的观感；提示里的摄像机指令能改变轨迹。数字世界（如游戏）片段被用来说明模拟而不只是「漂亮像素」。失败案例与成功案例并列，说明模拟是部分的、易碎的。</p><p><span class="marginnote">「最长约一分钟、高保真」是官方能力陈述，不是每个提示都能稳定到六十秒无崩溃。安全与虚假信息、人物肖像等产品约束在产品沟通里另述；技术博客的重点是表示与定性行为。不要编造公开的参数量或训练硬件表。</span></p><h3 id="与图像-dit-的差是维数-不是另一套生成论" tabindex="-1">与图像 DiT 的差是维数，不是另一套生成论 <a class="header-anchor" href="#与图像-dit-的差是维数-不是另一套生成论" aria-label="Permalink to &quot;与图像 DiT 的差是维数，不是另一套生成论&quot;">​</a></h3><p>图像 DiT：2D latent patch。Sora：压缩后的时空体积上的 3D patch。去噪对象都是「干净 token」。U-Net 视频模型常见的 3D 卷积时空块，在这篇博客里被 Transformer 加 patch 取代。未公开的部分包括：噪声日程、是否分类器自由引导、是否级联、是否潜空间与像素空间混合。讨论架构时停在博客句子，把细节标成未知。</p>',17)),(r(),t(l,null,{default:e(()=>[s(E,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%8E%9F%E5%A7%8B%E8%A7%86%E9%A2%91%20%2F%20%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20C%5B%22%E8%A7%86%E9%A2%91%E5%8E%8B%E7%BC%A9%E7%BD%91%E7%BB%9C%22%5D%0A%20%20C%20--%3E%20L%5B%22%E6%97%B6%E7%A9%BA%E6%BD%9C%E5%8F%98%E9%87%8F%22%5D%0A%20%20L%20--%3E%20P%5B%22%E5%88%87%E6%88%90%E6%97%B6%E7%A9%BA%20patch%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%8F%90%E7%A4%BA%20%2F%20%E9%87%8D%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20DT%5B%22%E6%89%A9%E6%95%A3%20Transformer%22%5D%0A%20%20P%20--%3E%20DT%0A%20%20DT%20--%3E%20Y%5B%22%E5%B9%B2%E5%87%80%20patch%22%5D%0A%20%20Y%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%E5%9B%9E%E5%83%8F%E7%B4%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>闭源。无法复现训练，无法做消融。评测是定性展示与已知失败模式，没有公开的 FVD 表。世界模拟器叙事容易被营销放大；工程上应把它当视频生成器：提示遵从、时间一致性、物理漏洞、文字与手部。可变分辨率意味着服务端要为不同网格备算力，博客未谈批处理。压缩伪影会成为生成伪影的上限。</p><p><span class="marginnote">常见误区：把「世界模拟器」读成「物理引擎」。博客在展示成功例子的同时列了失败清单——玻璃该碎不碎、因果、左右不分、文字渲染。物理观感是从数据里隐式学出来的统计规律，不是显式求解运动方程；碰上训练分布外的物理，照样穿帮。</span></p><p>不要引用非官方综述里的模块图当作 OpenAI 设计。不要把后来的原生音频（Sora 2 博客）写进 2024 年 2 月的 Sora。与 Veo 对比音频、4K、Flow 工具链时，用各自发布日的官方文本。</p><p><span class="marginnote">出处：OpenAI，<em>Video generation models as world simulators</em>，<a href="https://openai.com/index/video-generation-models-as-world-simulators/" target="_blank" rel="noreferrer">https://openai.com/index/video-generation-models-as-world-simulators/</a> （2024-02-15）。产品说明见 OpenAI <em>Sora: Creating video from text</em>。架构对照仅引用该文已点名的扩散 Transformer 传统，不补充未公开实现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sora 是文本条件的视频/图像潜空间扩散 Transformer，token 是时空 patch。</li><li>压缩网络在时间与空间上降维；可变时长与宽高比用网格大小表达。</li><li>官方把缩放视频生成写成通向世界模拟器的路径，并同时列出物理与因果失败。</li><li>技术博客不含模型与实现细节；评测与复现只能当黑盒。</li><li>图生视频、延长、编辑是产品接口，不是公开公式。</li><li>出处：OpenAI，<em>Video generation models as world simulators</em>，2024-02-15。</li></ul>',7))])}const u=i(B,[["render",d]]);export{_ as __pageData,u as default};
